@spec clipboard_spec  src=tests/specs/clipboard_spec.lua  loc=633  cases=16
@exercises midiManager (h.fm), trackerView (h.vm), editCursor (h.ec), clipboard (h.clipboard), trackerManager (h.tm)
@surface   fm:dump, vm:setGridSize, ec:setPos, ec:extendTo, ec:pos, clipboard:collect, ec:setSelection, clipboard:trimTop, clipboard:pasteClip, tm:deleteEvent, tm:flush, tm:addEvent, tm:getChannel
@harness   mk{seed.notes, seed.length, seed.ccs}

# Intent
  Stage-6 contract pins for the clipboard factory (newClipboard in
  viewManager.lua, scheduled to lift to clipboard.lua at 6d). These pin
  the wire format between collect and pasteClip — what shape collect
  produces, what trimTop preserves, what chanDelta means in multi mode —
  so the file move can't drift the contract silently.

# Helpers
  @fn noteCol(h, chan)  @ 9-13
  @fn stopForPart(h, colIdx, part)  @ 15-19
  @fn noteOn(h, chan, pitch)  @ 21-25

# Cases
  @case 'clipboard:collect on 1×1 pitch sel produces single-mode clip with row-relative event, no vel'  [harness]  @ 37-67
  @case 'clipboard:collect on pitch+vel-spanning single-col sel carries both parts'  [harness]  @ 76-94
  @case 'clipboard:collect on a *-part sel covers every part of the column'  [harness]  @ 101-116
  @case 'clipboard:trimTop drops top rows and re-indexes survivors'  [harness]  @ 124-144
  @case 'copy/paste carries intent ceiling, not the clipped tail'  [harness]  @ 152-182
  @case 'paste fit-clip against a blocker keeps intent; regrows when blocker removed'  [harness]  @ 189-232
  @case 'copy/paste a retrig host leaves the original host intact'  [harness]  @ 239-279
  @case 'clipboard:collect multi-col records chanDelta from leftmost col'  [harness]  @ 287-312
  @case 'arbitrary metadata survives note pitch-mode collect→paste round-trip'  [harness]  @ 323-351
  @case 'arbitrary metadata survives cc-mode collect→paste round-trip'  [harness]  @ 361-399
  @case 'paste of a pitch+vel clip imposes source vel, ignoring destination context'  [harness]  @ 408-441
  @case 'paste of a pitch-only note clip carries destination vel forward, not source vel'  [harness]  @ 449-479
  @case 'paste of a delay-only clip assigns delay onto existing destination notes'  [harness]  @ 488-517
  @case 'a hidden part rides with the note through a pitch-only copy'  [harness]  @ 526-553
  @case 'paste of a pitch-only clip fills a shown delay lane from the destination'  [harness]  @ 561-590
  @case 'paste of a vel-only clip writes its values into a cc lane'  [harness]  @ 599-630

